(* [comment removed for export] *)
Lemma bge_env : forall (S : rts RT) (m m' : mem) (Lr : list (Z * Z)) (S1 fr keli datai : Z) (rowsi : list Z) (kr datar RR pixt : Z) (vt : pixv)
    (DD ND w h wpld : Z),
  ART RT S m -> (forall e, In e Lr -> In e (rt_live RT S)) ->
  kel_obj Lr m keli 41 41 20 20 datai rowsi -> kel_obj Lr m kr 1 256 0 0 datar [RR] ->
  pix_obj Lr m pixt vt (mkCmapv 0 0 0 0) -> p_data vt <> 0 ->
  (forall q k x, In (q, k) Lr -> q <= x < q + k -> outside [(DD, DD + ND); (S1 + 64, S1 + 72); (S1 + 112, S1 + 120)] x) ->
  rw_cells asegs m (S1 + 40) [C8 (Z_to_bv 64 wpld)] -> rw_cells asegs m (S1 + 48) [C8 (Z_to_bv 64 DD)] ->
  rw_cells asegs m (S1 + 56) [C8 (Z_to_bv 64 (fr + 48))] -> rw_cells asegs m (S1 + 72) [C8 (Z_to_bv 64 (fr + 80))] ->
  rw_cells asegs m (S1 + 80) [C8 (Z_to_bv 64 (fr + 112))] -> rw_cells asegs m (S1 + 88) [C8 (Z_to_bv 64 (p_wpl vt))] ->
  rw_cells asegs m (S1 + 96) [C8 (Z_to_bv 64 (p_data vt))] -> rw_cells asegs m (S1 + 104) [C8 (Z_to_bv 64 (fr + 128))] ->
  rw_cells asegs m (S1 + 120) [C8 (Z_to_bv 64 (fr + 96))] ->
  rw_cells asegs m (fr + 32) [C4 (Z_to_bv 64 w)] -> rw_cells asegs m (fr + 48) [C4 (Z_to_bv 64 h)] ->
  rw_cells asegs m (fr + 96) [C4 (Z_to_bv 64 41)] -> rw_cells asegs m (fr + 80) [C4 (Z_to_bv 64 41)] ->
  rw_cells asegs m (fr + 128) [C4 (Z_to_bv 64 20)] -> rw_cells asegs m (fr + 112) [C4 (Z_to_bv 64 20)] ->
  rw_cells asegs m (fr + 144) [C8 (Z_to_bv 64 keli)] ->
  (fr + 256 <= DD \/ DD + ND <= fr) -> (fr + 256 <= S1 \/ S1 + 128 <= fr) -> (S1 + 128 <= DD \/ DD + ND <= S1) ->
  (DD + ND <= 0x7fff8000 \/ 0x10007fff8000 <= DD) -> (S1 + 128 <= 0x7fff8000 \/ 0x10007fff8000 <= S1) ->
  munch [(DD, DD + ND); (S1 + 64, S1 + 72); (S1 + 112, S1 + 120)] m m' -> wmono asegs m m' ->
  bge_ro (mk_bgp S1 (fr + 32) (fr + 48) (fr + 96) (fr + 80) (fr + 128) (fr + 112) (fr + 144) (p_data vt) (rsize vt) DD ND
