(* [comment removed for export] *)
Lemma bge_ok : forall (S : rts RT) (m : mem) (Lr : list (Z * Z)) (S1 fr keli datai : Z) (rowsi : list Z) (kr datar RR pixt : Z) (vt : pixv)
    (pixd : Z) (vd v : pixv),
  ART RT S m -> (forall e, In e Lr -> In e (rt_live RT S)) ->
  kel_obj Lr m keli 41 41 20 20 datai rowsi -> kel_obj Lr m kr 1 256 0 0 datar [RR] ->
  pix_obj Lr m pixt vt (mkCmapv 0 0 0 0) -> p_data vt <> 0 -> p_d vt = 8 ->
  pix_obj (rt_live RT S) m pixd vd (mkCmapv 0 0 0 0) -> p_data vd <> 0 -> p_d vd = 8 ->
  pix_hdr_ok v -> p_w vt = p_w v + 20 + 21 -> p_h vt = p_h v + 20 + 21 -> p_w vd = p_w v -> p_h vd = p_h v ->
  0 <= S1 -> S1 + 128 <= 2^47 ->
  bgp_ok (mk_bgp S1 (fr + 32) (fr + 48) (fr + 96) (fr + 80) (fr + 128) (fr + 112) (fr + 144) (p_data vt) (rsize vt) (p_data vd) (rsize vd)
